import { defineMiddleware } from "astro:middleware";

// Worker-rendered responses on a workers.dev host get the same noindex
// header public/_headers gives static assets there (_headers doesn't apply
// to responses generated by the Worker).
export const onRequest = defineMiddleware(async (context, next) => {
  const response = await next();
  if (context.url.hostname.endsWith(".workers.dev")) {
    response.headers.set("X-Robots-Tag", "noindex");
  }
  return response;
});
